#!/usr/bin/env python3
"""Generate the static Cloudflare Pages site from verified inventory and page copy."""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).parent
PUBLIC = ROOT / "public"
DOMAIN = "https://www.banyantrees.org"
PHONE = "727-644-9200"
TEL = "+17276449200"
inventory = json.loads((ROOT / "data/inventory.json").read_text())

NAV = [
    ("Young Trees", "/young-banyan-trees/"),
    ("Specimen Trees", "/specimen-trees/"),
    ("For Professionals", "/for-professionals/"),
    ("Care Guide", "/banyan-tree-care-tampa-bay/"),
    ("Our Approach", "/our-approach/"),
]

def button(label, href, style="solid", extra=""):
    return f'<a class="button button--{style} {extra}" href="{href}">{label}<span aria-hidden="true">↗</span></a>'

def kicker(text):
    return f'<p class="eyebrow">{text}</p>'

def section_head(label, heading, body=""):
    return f'{kicker(label)}<h2>{heading}</h2>' + (f'<p class="lead">{body}</p>' if body else '')

def image(alt, cls="", lazy=True):
    return f'<img class="{cls}" src="/assets/banyan-tree-urban-farm-1200.webp" srcset="/assets/banyan-tree-urban-farm-800.webp 800w, /assets/banyan-tree-urban-farm-1200.webp 1200w" sizes="(max-width: 760px) 100vw, 60vw" width="1200" height="800" alt="{alt}" {"loading=lazy" if lazy else "fetchpriority=high"}>'

def band(label, title, text, cta="Call to discuss your tree", href=f"tel:{TEL}"):
    return f'''<section class="contact-band"><div class="wrap contact-band__inner"><div>{kicker(label)}<h2>{title}</h2><p>{text}</p></div>{button(cta, href, "light")}</div></section>'''

def layout(title, description, path, content, page_class="", schema=""):
    url = DOMAIN + path
    nav = ''.join(f'<a href="{href}" {"aria-current=page" if href == path else ""}>{label}</a>' for label, href in NAV)
    crumbs = '' if path == '/' else f'<nav class="breadcrumbs wrap" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>{escape(title.split(" | ")[0])}</span></nav>'
    org = {"@context":"https://schema.org","@type":"Organization","name":"The Banyan Tree Company","url":DOMAIN+"/","telephone":"+1-727-644-9200","areaServed":["St. Petersburg, Florida","Tampa, Florida","Clearwater, Florida","Sarasota, Florida"]}
    structured = json.dumps(org, ensure_ascii=False).replace("<", "\\u003c")
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)} | The Banyan Tree Company</title><meta name="description" content="{escape(description, quote=True)}">
<meta name="theme-color" content="#18231D"><meta name="robots" content="index,follow,max-image-preview:large">
<link rel="canonical" href="{url}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="icon" href="/favicon.ico"><link rel="apple-touch-icon" href="/apple-touch-icon.png">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=IBM+Plex+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="/assets/site.css?v=2"><script src="/assets/site.js?v=2" defer></script>
<meta property="og:type" content="website"><meta property="og:site_name" content="The Banyan Tree Company"><meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{DOMAIN}/assets/banyan-tree-company-og.jpg"><meta name="twitter:card" content="summary_large_image">
<script type="application/ld+json">{structured}</script>{schema}</head>
<body class="{page_class}"><a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><div class="wrap site-header__inner"><a class="brand" href="/" aria-label="The Banyan Tree Company home"><span class="brand__mark" aria-hidden="true">✳</span><span class="brand__text">THE BANYAN<br>TREE COMPANY</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">Menu <span aria-hidden="true">☰</span></button><nav class="site-nav" id="site-nav" aria-label="Main navigation">{nav}<a class="nav-cta" href="/consultation/">Start a Conversation <span aria-hidden="true">↗</span></a></nav></div></header>
<main id="main">{crumbs}{content}</main>
<footer class="site-footer"><div class="wrap footer-grid"><div><a class="brand brand--footer" href="/"><span class="brand__mark" aria-hidden="true">✳</span><span class="brand__text">THE BANYAN<br>TREE COMPANY</span></a><p>A living landmark for the landscape.<br>St. Petersburg · Tampa Bay · Gulf Coast</p></div><nav aria-label="Footer navigation"><a href="/young-banyan-trees/">Young Trees</a><a href="/specimen-trees/">Specimen Trees</a><a href="/for-professionals/">For Professionals</a><a href="/banyan-tree-care-tampa-bay/">Care Guide</a></nav><div class="footer-contact"><span class="eyebrow">START A CONVERSATION</span><a class="footer-phone" href="tel:{TEL}">{PHONE}</a><a href="/consultation/">Prepare a project brief ↗</a></div></div><div class="wrap footer-bottom"><span>© 2026 The Banyan Tree Company</span><span><a href="/privacy/">Privacy</a> · <a href="/sitemap.xml">Sitemap</a></span></div></footer>
<a class="mobile-call" href="tel:{TEL}">Call {PHONE} <span aria-hidden="true">↗</span></a></body></html>'''

def write(path, title, description, body, cls=""):
    target = PUBLIC / path.lstrip('/') / 'index.html' if path != '/' else PUBLIC / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(layout(title, description, path, body, cls))

home = f'''
<section class="hero"><div class="hero__photo" aria-hidden="true"></div><div class="wrap hero__inner"><div class="hero__content">{kicker('BANYAN TREES · TAMPA BAY, FLORIDA')}<h1>A living landmark<br>for the <em>landscape.</em></h1><p>Young banyans delivered to your door. Mature specimen trees sourced for properties and projects that call for something extraordinary.</p><div class="actions">{button('Explore Young Trees','/young-banyan-trees/','light')}{button('Source a Specimen','/specimen-trees/','outline-light')}</div></div><p class="hero__caption">ST. PETERSBURG · TAMPA · CLEARWATER · SARASOTA</p></div></section>
<section class="intro-section section"><div class="wrap intro-grid"><div>{kicker('THE COLLECTION')}<h2>Grow the story.<br><em>Or arrive with one.</em></h2></div><p class="lead">A banyan changes the scale and feeling of a place. Begin with a young tree and watch its form take shape, or discuss a mature centerpiece for a project that needs presence now.</p></div></section>
<section class="offer-section"><div class="wrap offer-grid"><a class="offer-card offer-card--young" href="/young-banyan-trees/"><span class="offer-card__number">01 / THE BEGINNING</span><div><h3>Young trees,<br><em>delivered.</em></h3><p>Explore the young-tree collection and ask about local availability and delivery.</p><span class="text-link">Explore Young Trees <b aria-hidden="true">↗</b></span></div></a><a class="offer-card offer-card--mature" href="/specimen-trees/"><span class="offer-card__number">02 / THE CENTERPIECE</span><div><h3>A specimen<br><em>with presence.</em></h3><p>Bring us the site, the scale and the vision. We will begin with a conversation about fit.</p><span class="text-link">Explore Specimen Trees <b aria-hidden="true">↗</b></span></div></a></div></section>
<section class="section philosophy"><div class="wrap split"><figure class="image-frame">{image('The canopy and aerial roots of a mature banyan tree')}<figcaption>FORM / SCALE / PLACE</figcaption></figure><div class="split__copy">{kicker('RIGHT TREE, RIGHT PLACE')}<h2>Beauty needs room to become its own.</h2><p>Canopy, roots, coastal exposure and nearby structures deserve as much attention as appearance. A banyan is a long-term landscape decision. Start with the botanical identity and the site.</p>{button('Read the Care Guide','/banyan-tree-care-tampa-bay/','text')}</div></div></section>
<section class="section process"><div class="wrap">{section_head('THE PROCESS','A considered way to begin.','Whether you are choosing a young tree or planning a signature installation, the best result starts with a useful brief.')}<div class="steps"><article><span>01</span><h3>Tell us the setting</h3><p>Share the location, available space and the role the tree should play.</p></article><article><span>02</span><h3>Explore the right scale</h3><p>Discuss young trees or a mature specimen that suits the intended setting.</p></article><article><span>03</span><h3>Plan the next step</h3><p>Review availability, site considerations and delivery or project scope.</p></article></div></div></section>
{band('BEGIN WITH THE SITE','Give the landscape its defining moment.','Tell us where the tree will live and what you want it to become.','Start a Conversation','/consultation/')}
'''
write('/', 'Banyan Trees for Tampa Bay Landscapes', 'Explore young banyan trees and mature specimen sourcing for distinctive Tampa Bay landscapes. Based in St. Petersburg, Florida.', home, 'home')

